class Solution {
public:
    vector<string> pad = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    vector<string> res;
    string path;
    void go(string& digits, int i) {
        if (i == (int)digits.size()) {
            res.push_back(path);
            return;
        }
        string keys = pad[digits[i] - '0'];
        for (char c : keys) {
            path.push_back(c);
            go(digits, i + 1);
            path.pop_back();
        }
    }
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};
        go(digits, 0);
        return res;
    }
};
